CREATE TABLE Users(Id INT IDENTITY PRIMARY KEY, Role NVARCHAR(50), FIO NVARCHAR(200), Login NVARCHAR(200), Password NVARCHAR(100));
CREATE TABLE PickupPoints(Id INT IDENTITY PRIMARY KEY, Address NVARCHAR(300));
CREATE TABLE Products(Article NVARCHAR(20) PRIMARY KEY, Name NVARCHAR(300), Unit NVARCHAR(20), Price DECIMAL(12,2), Supplier NVARCHAR(200), Manufacturer NVARCHAR(200), Category NVARCHAR(200), Discount INT, Stock INT, Description NVARCHAR(MAX), Photo NVARCHAR(200));
CREATE TABLE Orders(Id INT PRIMARY KEY, OrderDate DATE, DeliveryDate DATE, PickupPointId INT REFERENCES PickupPoints(Id), ClientFIO NVARCHAR(200), Code INT, Status NVARCHAR(50));
CREATE TABLE OrderItems(Id INT IDENTITY PRIMARY KEY, OrderId INT REFERENCES Orders(Id), Article NVARCHAR(20) REFERENCES Products(Article), Qty INT);
