INSERT INTO Products VALUES(N'А112Т4',N'Прихожая Фаворит 1 1420х2056х352ммм Дуб Делано/Цемент Светлый SV-М 1 шт',N'шт.',9577,N'Стройландия',N'SVМЕБЕЛЬ',N'Прихожая',10,0,N'Удивительно функциональная и практичная прихожая Фаворит 1, обладая характерными чертами Скандинавского стиля, выглядит эффектно и способна задать тон интерьеру дома, встречая вас и ваших гостей. ',N'1.jpg');
INSERT INTO Products VALUES(N'G843H5',N'Прихожая в коридор Твист с зеркалом мебель со шкафами, 120х37х202 см',N'шт.',8803,N'Стройландия',N'Мебелони',N'Прихожая',25,9,N'Этот стеллаж со шкафом в прихожую комнату станет отличным элементом для вашего интерьера. Мебель для дома обеспечивает удобное хранение перчаток, шапок, зонтов, сумок и других аксессуаров. ',N'2.jpg');
INSERT INTO Products VALUES(N'D325D4',N'Угловой диван Кромма Инвуд Лайт, серый двухместный диван, Velutto 32',N'шт.',29125,N'Кромма',N'Инвуд',N'Диван',5,12,N'Угловой диван Инвуд Лайт 2 - стильный и комфортный диван подойдет для комнаты любого размера.',N'3.jpg');
INSERT INTO Products VALUES(N'S432T5',N'Обувница RIDBERG, с вешалкой, стальная, 170x60x26 см, 5 полок, вместимость до 15 пар',N'шт.',885,N'Кромма',N'RIDBERG',N'Обувница',15,15,N'Обувница Ridberg с 5 полками и вешалкой - идеальное решение для организации хранения обуви в прихожей или гардеробной. ',N'4.jpg');
INSERT INTO Products VALUES(N'F325D4',N'Диван, Прямой диван, Диван-кровать Сити темно-коричневый. Квест-33',N'шт.',14322,N'ЗолотоеРуно',N'Инвуд',N'Диван',18,3,N'
INSERT INTO Products VALUES(N'G432G6',N'Пуф трансформер кровать раскладушка светло-коричневый велюр',N'шт.',6149,N'KRYLOVMANUFACTURA',N'Инвуд',N'Пуф',22,3,N'Пуф трансформер 5в1 представляет собой уникальное сочетание функций, выступая в качестве пуфика, столика, кресла, шезлонга и дополнительного спального места. ',N'6.jpg');
INSERT INTO Products VALUES(N'H542F5',N'Диван, Прямой диван, диван кровать, Рио симпл механизм Пантограф. Симпл-16',N'шт.',20708,N'ЗолотоеРуно',N'Инвуд',N'Диван',4,5,N'Диван Рио симпл от "Золотое Руно" - это сочетание комфорта, функциональности и стильного дизайна.',N'7.jpg');
INSERT INTO Products VALUES(N'C346F5',N'Полка настенная ромб Лофт, черная, 40 см',N'шт.',2843,N'KRYLOVMANUFACTURA',N'RIDBERG',N'Полка',5,4,N'Полочки для цветов в стиле лофт. Подойдут как для цветов, так и в качестве декоративного элемента. Полки подойдут для дома, офиса, кафе, ресторана. ​',N'8.jpg');
INSERT INTO Products VALUES(N'F256G6',N'Стулья для кухни',N'шт.',4760,N'KRYLOVMANUFACTURA',N'RIDBERG',N'Стул',6,2,N'Набор из четырех стульев в лофт-дизайне станет любимой мебелью для отдыха и подойдет для взрослых и детей. ',N'9.jpg');
INSERT INTO Products VALUES(N'J532V5',N'Магнитная полка, для холодильника, металл, 3шт, универсальная, чёрная',N'шт.',1387,N'KRYLOVMANUFACTURA',N'RIDBERG',N'Полка',8,6,N'Магнитная полка для холодильника - это удобный и практичный аксессуар, который поможет организовать пространство в вашем доме.',N'10.jpg');
